import express from 'express';
import cors from 'cors';
import { randomUUID } from 'crypto';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { InMemoryEventStore } from '@modelcontextprotocol/sdk/examples/shared/inMemoryEventStore.js';
import { MCPServer } from './server.js';
import { WalletOrchestrator } from '../services/WalletOrchestrator.js';
import { initializeServices } from './stdio-server.js';

interface SessionContext {
  transport: StreamableHTTPServerTransport;
  orchestrator: WalletOrchestrator;
  services: ServiceDependencies;
  agentId: string;
  createdAt: Date;
}

const app = express();
app.use(express.json());
app.use(cors({
  origin: '*',
  methods: 'GET,POST,DELETE',
  exposedHeaders: ['mcp-session-id', 'last-event-id', 'mcp-protocol-version']
}));

const sessions = new Map<string, SessionContext>();

app.post('/mcp', async (req, res) => {
  const sessionId = req.headers['mcp-session-id'] as string | undefined;

  if (sessionId && sessions.has(sessionId)) {
    const session = sessions.get(sessionId)!;
    await session.transport.handleRequest(req, res, req.body);
  } else if (!sessionId) {
    const { services, orchestrator } = await initializeServices();
    const mcpServer = new MCPServer(services, { name: 'midnight-mcp', version: '2.0.0' });
    const server = mcpServer.getServer();
    const eventStore = new InMemoryEventStore();

    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: () => randomUUID(),
      eventStore,
      onsessioninitialized: (sid) => {
        sessions.set(sid, {
          transport,
          orchestrator,
          services,
          agentId: process.env.AGENT_ID || 'default',
          createdAt: new Date()
        });
        console.log(`Session created: ${sid}`);
      }
    });

    server.onclose = async () => {
      const sid = transport.sessionId;
      if (sid && sessions.has(sid)) {
        const session = sessions.get(sid)!;
        await session.orchestrator.stop();
        sessions.delete(sid);
        console.log(`Session closed: ${sid}`);
      }
    };

    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } else {
    res.status(400).json({ jsonrpc: '2.0', error: { code: -32000, message: 'Invalid session' }, id: null });
  }
});

app.get('/mcp', async (req, res) => {
  const sessionId = req.headers['mcp-session-id'] as string | undefined;
  if (!sessionId || !sessions.has(sessionId)) {
    res.status(400).json({ jsonrpc: '2.0', error: { code: -32000, message: 'Invalid session' }, id: null });
    return;
  }
  const session = sessions.get(sessionId)!;
  await session.transport.handleRequest(req, res);
});

app.delete('/mcp', async (req, res) => {
  const sessionId = req.headers['mcp-session-id'] as string | undefined;
  if (!sessionId || !sessions.has(sessionId)) {
    res.status(400).json({ jsonrpc: '2.0', error: { code: -32000, message: 'Invalid session' }, id: null });
    return;
  }
  const session = sessions.get(sessionId)!;
  await session.transport.handleRequest(req, res);
});

app.get('/health', (req, res) => {
  res.json({ status: 'healthy', sessions: sessions.size, uptime: process.uptime() });
});

const port = parseInt(process.env.PORT || '3000');
const httpServer = app.listen(port, () => console.log(`MCP HTTP Server on http://localhost:${port}/mcp`));

process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  httpServer.close();
  for (const [sid, session] of sessions) {
    await session.orchestrator.stop();
    session.transport.close();
  }
  process.exit(0);
});

